import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.moment.GeometricMean;
import org.apache.commons.math.stat.descriptive.moment.Mean;
import org.apache.commons.math.stat.descriptive.moment.SecondMoment;
import org.apache.commons.math.stat.descriptive.moment.Variance;
import org.apache.commons.math.stat.descriptive.rank.Max;
import org.apache.commons.math.stat.descriptive.rank.Min;
import org.apache.commons.math.stat.descriptive.summary.Sum;
import org.apache.commons.math.stat.descriptive.summary.SumOfLogs;
import org.apache.commons.math.stat.descriptive.summary.SumOfSquares;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math.util.Precision;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for SummaryStatistics.toString()
 */
public class SummaryStatistics_toString_TriageGen1Test {

    @Test
    public void testToStringWithData() {
        SummaryStatistics stats = new SummaryStatistics();
        stats.addValue(2.0);
        stats.addValue(8.0);

        // Expected values:
        // n: 2
        // min: 2.0
        // max: 8.0
        // mean: 5.0
        // geometric mean: sqrt(2*8) = 4.0
        // variance: ((2-5)^2 + (8-5)^2) / (2-1) = (9 + 9) / 1 = 18.0
        // sum of squares: 2^2 + 8^2 = 4 + 64 = 68.0
        // standard deviation: sqrt(18) ≈ 4.242640687119285
        // sum of logs: ln(2) + ln(8) ≈ 0.6931471805599453 + 2.0794415416798357 = 2.772588722239781

        String result = stats.toString();

        StringBuilder expected = new StringBuilder();
        expected.append("SummaryStatistics:\n");
        expected.append("n: 2\n");
        expected.append("min: 2.0\n");
        expected.append("max: 8.0\n");
        expected.append("mean: 5.0\n");
        expected.append("geometric mean: 4.0\n");
        expected.append("variance: 18.0\n");
        expected.append("sum of squares: 68.0\n");
        expected.append("standard deviation: ").append(stats.getStandardDeviation()).append("\n");
        expected.append("sum of logs: ").append(stats.getSumOfLogs()).append("\n");

        assertEquals(expected.toString(), result);
    }




}

