        // When empty, Apache Commons Math returns NaN for most metrics and 0 for n
        StringBuilder expected = new StringBuilder();
        expected.append("SummaryStatistics:\n");
        expected.append("n: 0\n");
        expected.append("min: ").append(stats.getMin()).append("\n");
